#!/usr/bin/env python3
"""Offline migration through public CLI entry points; synthetic source only."""
import argparse
import hashlib
import json
import sqlite3
import subprocess
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BIN = ROOT / "target/debug/fleetpane-host"

def fixture(root):
    root.mkdir(parents=True, exist_ok=True)
    home, cwd, codex, dsh = [root / n for n in ("paseo", "工作区", "codex", "dsh")]
    for path in (home / "projects", home / "agents/project", cwd, codex, dsh):
        path.mkdir(parents=True, exist_ok=True)
    def write(path, value):
        path.write_text(json.dumps(value, ensure_ascii=False))
    write(home / "projects/workspaces.json", [{"workspaceId":"workspace-one", "projectId":"project-one", "cwd":str(cwd), "kind":"directory", "displayName":"迁移工作区", "branch":"fixture-branch", "archivedAt":None}])
    for identity, provider in (("codex-one", "codex"), ("dsh-one", "deepseek-harness"), ("unsupported-one", "claude")):
        write(home / f"agents/project/{identity}.json", {"id":identity,"provider":provider,"cwd":str(cwd),"workspaceId":"workspace-one","title":f"Imported {identity}","lastStatus":"idle","persistence":{"provider":provider,"sessionId":identity},"config":{"apiKey":"SYNTHETIC_DO_NOT_COPY"}})
    def msg(role, text):
        return {"type":"response_item","payload":{"type":"message","role":role,"content":[{"type":"input_text" if role=="user" else "output_text", "text":text}]}}
    records = [
        {"type":"session_meta","payload":{"id":"codex-one","cwd":str(cwd)}},
        msg("user", "迁移后仍然保留的提问"),
        msg("assistant", "## Migrated Markdown\n\n中文 **bold** and `code`.\n\n| Provider | History |\n| --- | --- |\n| Codex | Copied |\n\n```rust\nprintln!(\"migrated\");\n```"),
        {"type":"response_item","payload":{"type":"function_call","name":"exec_command","call_id":"tool-one","arguments":"{\"cmd\":\"printf migrated\"}"}},
        {"type":"response_item","payload":{"type":"function_call_output","call_id":"tool-one","output":"MIGRATED_TOOL_OUTPUT\n中文 output"}},
        {"type":"response_item","payload":{"type":"message","role":"user","content":[{"type":"input_image","image_url":"data:image/png;base64,"}]}},
    ] + [msg("assistant", f"Migrated older item {i}") for i in range(40)]
    log = codex / "history.jsonl"
    log.write_text("".join(json.dumps(r, ensure_ascii=False)+"\n" for r in records))
    with sqlite3.connect(codex / "state_5.sqlite") as db:
        db.execute("CREATE TABLE threads(id TEXT PRIMARY KEY,rollout_path TEXT)")
        db.execute("INSERT INTO threads VALUES(?,?)",("codex-one",str(log)))
    key="--"+str(cwd).replace("/","-").lstrip("-").replace("工作区","~5DE5~4F5C~533A")+"--"
    directory=dsh / "sessions" / key / "dsh-one"
    directory.mkdir(parents=True)
    records=[{"type":"session","version":3,"id":"dsh-one","cwd":str(cwd)}, {"type":"user/message","data":{"content":[{"type":"text","text":"DeepSeek 历史问题"}]}}, {"type":"assistant/message","data":{"message":{"content":[{"type":"text","text":"## Migrated DeepSeek\n\nHistory is **durable**."}]}}}]
    (directory/"session.v3.jsonl").write_text("".join(json.dumps(r)+"\n" for r in records))
    config=root/"hosts.json"
    write(config,{"version":1,"hosts":[{"name":"Migration QA","socket":str(root/"unstarted.sock")}]})
    return home,codex,dsh,config

def check(root):
    home,codex,dsh,config=fixture(root)
    store=root/"hosts.creations"
    def command(*args, ok=True):
        p=subprocess.run([str(BIN),"paseo-import",*map(str,args)],capture_output=True,text=True,timeout=20)
        assert (p.returncode==0)==ok,p.stderr
        return json.loads(p.stdout) if ok else p.stderr
    def hashes():
        return {str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest() for base in (home,codex,dsh) for p in base.rglob("*") if p.is_file()}
    original=hashes()
    preview=command("preview",home)
    assert not store.exists()
    assert "SYNTHETIC_DO_NOT_COPY" not in json.dumps(preview)
    imported=command("workspace",store,home,preview["candidates"][0]["revision"],config,"Migration QA","workspace-one")
    assert imported["session_count"]==3 and imported["workspace_id"]
    repeated=command("workspace",store,home,preview["candidates"][0]["revision"],config,"Migration QA","workspace-one")
    assert repeated["id"]==imported["id"]
    report=command("copy-workspace-history",store,imported["id"],codex,dsh)
    assert report["copied"]==2 and len(report["failures"])==1,report
    sessions=command("sessions",store,imported["id"])
    codex_session=next(s for s in sessions if s["agent"]["provider"]=="codex")
    first=command("history",store,codex_session["id"],0)
    assert len(first["items"])==32 and first["next"]==32
    second=command("history",store,codex_session["id"],first["next"])
    assert len(second["items"])==13 and second["next"] is None
    assert first["status"]["source_records"]==46
    assert command("source-record",store,codex_session["id"],5)["payload"]["output"]=="MIGRATED_TOOL_OUTPUT\n中文 output"
    assert hashes()==original
    log=codex/"history.jsonl"
    saved=log.read_bytes();log.unlink()
    assert command("history",store,codex_session["id"],0)==first
    assert command("copy-history",store,codex_session["id"],codex,dsh)["rows"]==45
    log.write_bytes(saved)
    assert not (root/"unstarted.sock").exists()
    with sqlite3.connect(store/"creations.sqlite3") as db:
        assert db.execute("PRAGMA user_version").fetchone()[0]==11
    print(json.dumps({"offline_workspace_and_history":"PASS","idempotent_import":"PASS","durable_paged_history":"PASS","explicit_unsupported_provider":"PASS","source_unchanged":"PASS","no_host_required":"PASS"}))

if __name__=="__main__":
    parser=argparse.ArgumentParser();parser.add_argument("--fixture",type=Path);args=parser.parse_args()
    if args.fixture:
        fixture(args.fixture.resolve());print(args.fixture.resolve())
    else:
        with tempfile.TemporaryDirectory(prefix="fleetpane-paseo-import-") as directory:check(Path(directory))
